package com.fasterxml.jackson.databind.type;

import com.fasterxml.jackson.databind.JavaType;
import java.io.*;
import java.lang.reflect.Method;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

public class ReferenceType_buildCanonicalName_TriageGen0Test {

    /**
     * Since buildCanonicalName is protected, we use reflection to access it.
     * We use the 'construct' factory method to create instances of ReferenceType.
     */
    @Test
    public void testBuildCanonicalName() throws Exception {
        // Setup Mock dependencies
        Class<?> clazz = String.class;
        JavaType mockRefType = mock(JavaType.class);
        when(mockRefType.toCanonical()).thenReturn("java.lang.String");

        // Use the public static construct method to create the ReferenceType instance
        // ReferenceType.construct(Class<?> cls, JavaType refType)
        ReferenceType referenceType = ReferenceType.construct(clazz, mockRefType);

        // Access the protected method via reflection
        Method method = ReferenceType.class.getDeclaredMethod("buildCanonicalName");
        method.setAccessible(true);

        // Execute
        String result = (String) method.invoke(referenceType);

        // Verify
        // Expected format: _class.getName() + '<' + _referencedType.toCanonical()
        String expected = "java.lang.String<java.lang.String";
        assertEquals(expected, result);
    }


}

package com.fasterxml.jackson.databind.type;

