public class ReferenceType_buildCanonicalName_TriageGen0Test {



    @Test
    public void testBuildCanonicalNameWithComplexType() throws Exception {
        // Setup Mock dependencies for a more complex scenario
        Class<?> clazz = java.util.List.class;
        JavaType mockRefType = mock(JavaType.class);
        // Simulating a nested canonical name
        when(mockRefType.toCanonical()).thenReturn("java.util.List<java.lang.Integer>");

        ReferenceType referenceType = ReferenceType.construct(clazz, mockRefType);

        Method method = ReferenceType.class.getDeclaredMethod("buildCanonicalName");
        method.setAccessible(true);

        // Execute
        String result = (String) method.invoke(referenceType);

        // Verify
        String expected = "java.util.List<java.util.List<java.lang.Integer>";
        assertEquals(expected, result);
    }
}
